INSERT INTO utility (utility_name, program_name, program_type, program_details, sign_up_incentive, ongoing_incentive)
VALUES
    ('Kinetic Energy Ltd', 'Dynamic Pricing', 'DP', '{"title": "Dynamic Pricing", "description_1": "Your Dynamic Pricing program allows Ford to set charging schedules for your electric vehicles which means your vehicle will charge at times of the day when energy is cheaper.", "description_2": "Using hourly pricing data sent by Kinetic Energy Ltd, Ford will generate a smart schedule to charge your car to your desired percentage of charge meaning you save money per charge as well as being rewarded for participating.", "enrollment_desc": "as well as a $50 bonus just for signing up. ", "charging_incentives_desc": "$1 per every kwh shifted just for following your schedule"}', 50.00, 1.00),
    ('Solar Energy', 'Dynamic Pricing', 'DP', '{"title": "Dynamic Pricing", "description_1": "Your Dynamic Pricing program allows Ford to set charging schedules for your electric vehicles which means your vehicle will charge at times of the day when energy is cheaper.", "description_2": "Using hourly pricing data sent by Solar Energy, Ford will generate a smart schedule to charge your car to your desired percentage of charge meaning you save money per charge as well as being rewarded for participating.", "enrollment_desc": "as well as a $75 bonus just for signing up. ", "charging_incentives_desc": "$1.50 per every kwh shifted just for following your schedule"}', 75.00, 1.50),
    ('Smith Utilities', 'Demand Response', 'DR', '{"title": "Demand Response","description_1": "Smith Utilities can send a request to Ford to stop all charging at a requested time to prevent overloading the grid, by participating in these events and allowing Ford to pause your charging you can receive:","charging_incentives_desc": "Earn $10 per DR event you participate in"}', 00.00, 10.00),
    ('Electrical Energy Ltd', 'Demand Response', 'DR', '{"title": "Demand Response","description_1": "Electrical Energy Ltd can send a request to Ford to stop all charging at a requested time to prevent overloading the grid, by participating in these events and allowing Ford to pause your charging you can receive:", "enrollment_desc": "Earn $50, for enrolling your eligible vehicle in the program.", "charging_incentives_desc": "Earn $5 per DR event you participate in"}', 50.00, 5.00);